+    return;
+  }
+  if (model.wires[primitiveId]) {
+    visit(primitiveId);
+    for (const edgeId of model.wires[primitiveId]!.edgeIds) visitPrimitiveClosure(model, edgeId, visit);
+    return;
+  }
+  if (model.faces[primitiveId]) {
+    visit(primitiveId);
+    for (const wireId of model.faces[primitiveId]!.wireIds) visitPrimitiveClosure(model, wireId, visit);
+    return;
+  }
+  if (model.shells[primitiveId]) {
+    visit(primitiveId);
+    for (const faceId of model.shells[primitiveId]!.faceIds) visitPrimitiveClosure(model, faceId, visit);
+    return;
+  }
+  if (model.solids[primitiveId]) {
+    visit(primitiveId);
+    for (const shellId of model.solids[primitiveId]!.shellIds) visitPrimitiveClosure(model, shellId, visit);
+  }
