+function primitiveJsonFromModel(model: Model, primitiveId: string, slot?: string): SpatialObjectPrimitiveJson | null {
+  const attributes = primitiveAttributesFromModel(model, primitiveId);
+  const withMaybeAttributes = <T extends { readonly id: string; readonly kind: kernelGeometry.GeometryEntityKind }>(row: T): T | (T & { readonly attributes: Readonly<Record<string, unknown>> }) =>
+    attributes ? { ...row, attributes } : row;
+  if (model.anchors[primitiveId]) return withMaybeAttributes({ kind: "anchor", ...(slot ? { slot } : {}), ...model.anchors[primitiveId]! });
+  if (model.vertices[primitiveId]) return withMaybeAttributes({ kind: "vertex", ...(slot ? { slot } : {}), ...model.vertices[primitiveId]! });
+  if (model.edges[primitiveId]) return withMaybeAttributes({ kind: "edge", ...(slot ? { slot } : {}), ...model.edges[primitiveId]! });
+  if (model.wires[primitiveId]) return withMaybeAttributes({ kind: "wire", ...(slot ? { slot } : {}), ...model.wires[primitiveId]! });
+  if (model.faces[primitiveId]) return withMaybeAttributes({ kind: "face", ...(slot ? { slot } : {}), ...model.faces[primitiveId]! });
+  if (model.shells[primitiveId]) return withMaybeAttributes({ kind: "shell", ...(slot ? { slot } : {}), ...model.shells[primitiveId]! });
+  if (model.solids[primitiveId]) return withMaybeAttributes({ kind: "solid", ...(slot ? { slot } : {}), ...model.solids[primitiveId]! });
+  return null;
