+  const childIds = new Set<string>();
+  for (const row of Object.values(model.anchors)) childIds.add(row.attachment.id);
+  for (const row of Object.values(model.edges)) for (const vertexId of row.vertexIds) childIds.add(vertexId);
+  for (const row of Object.values(model.wires)) for (const edgeId of row.edgeIds) childIds.add(edgeId);
+  for (const row of Object.values(model.faces)) for (const wireId of row.wireIds) childIds.add(wireId);
+  for (const row of Object.values(model.shells)) for (const faceId of row.faceIds) childIds.add(faceId);
+  for (const row of Object.values(model.solids)) for (const shellId of row.shellIds) childIds.add(shellId);
+  const candidates = [
+    ...Object.keys(model.solids),
+    ...Object.keys(model.shells),
+    ...Object.keys(model.faces),
+    ...Object.keys(model.wires),
+    ...Object.keys(model.edges),
+    ...Object.keys(model.vertices),
+    ...Object.keys(model.anchors),
