+    typology: KERNEL_TOPOLOGY_TYPOLOGY_IDS[kind] as TypologyRef,
+    primitives: { [kind]: primitiveId },
+  };
+}
+
+function serializeModelObjects(model: Model): readonly SpatialObjectJsonRecord[] {
+  const explicitObjects = sortedRecordValues(model.objects).map((object) => ({
+    id: object.id,
+    typology: object.typology,
+    primitives: collectObjectPrimitiveJson(model, object),
+    ...(object.attributes ? { attributes: object.attributes } : {}),
+  }));
+  const ownedPrimitiveIds = new Set<string>(Object.values(model.objects).flatMap((object) => objectPrimitiveRefs(object)));
+  const syntheticObjects = unownedRootPrimitiveIds(model, ownedPrimitiveIds)
+    .map((primitiveId) => syntheticObjectRecordForPrimitive(model, primitiveId))
+    .filter((object): object is SpatialObjectRecord => object !== null)
+    .map((object) => ({ id: object.id, typology: object.typology, primitives: collectObjectPrimitiveJson(model, object) }));
+  return [...explicitObjects, ...syntheticObjects].sort((left, right) => left.id.localeCompare(right.id));
+}
