tool_input.command:
Set-Location "c:\git\compose"; $script = @'
import { readFile, writeFile } from "node:fs/promises";

const files = [
  "spatial/fixtures/geometry.json",
  "spatial/fixtures/geometry-loom.json",
  "spatial/fixtures/geometry-routes.json",
  "spatial/fixtures/small-building.model.json",
  "spatial/fixtures/tall-building.model.json",
  "spatial/fixtures/large-building.model.json",
  "spatial/fixtures/simple.spatial.json",
];

const kindOrder = { anchor: 0, vertex: 1, edge: 2, wire: 3, face: 4, shell: 5, solid: 6 };
const kernelTypology = {
  anchor: "spatial.shape.kernel.anchor",
  vertex: "spatial.shape.kernel.vertex",
  edge: "spatial.shape.kernel.edge",
  wire: "spatial.shape.kernel.wire",
  face: "spatial.shape.kernel.face",
  shell: "spatial.shape.kernel.shell",
  solid: "spatial.shape.kernel.solid",
};

const normalizeObjects = (rawObjects) => Array.isArray(rawObjects) ? rawObjects : [];
const normalizeGeometry = (rawModel) => {
  const geometry = rawModel && typeof rawModel.geometry === "object" ? rawModel.geometry : rawModel;
  return {
    anchors: Array.isArray(geometry?.anchors) ? geometry.anchors : [],
    vertices: Array.isArray(geometry?.vertices) ? geometry.vertices : [],
    edges: Array.isArray(geometry?.edges) ? geometry.edges : [],
    wires: Array.isArray(geometry?.wires) ? geometry.wires : [],
    faces: Array.isArray(geometry?.faces) ? geometry.faces : [],
    shells: Array.isArray(geometry?.shells) ? geometry.shells : [],
    solids: Array.isArray(geometry?.solids) ? geometry.solids : [],
  };
};

const resolvePrimitiveKind = (tables, id) => {
  if (tables.anchors[id]) return "anchor";
  if (tables.vertices[id]) return "vertex";
  if (tables.edges[id]) return "edge";
  if (tables.wires[id]) return "wire";
  if (tables.faces[id]) return "face";
  if (tables.shells[id]) return "shell";
  if (tables.solids[id]) return "solid";
  return null;
};

const visitPrimitiveClosure = (tables, id, visit) => {
  const kind = resolvePrimitiveKind(tables, id);
  if (!kind) return;
  visit(id);
  if (kind === "anchor") visitPrimitiveClosure(tables, tables.anchors[id].attachment.id, visit);
  if (kind === "edge") for (const vertexId of tables.edges[id].vertexIds) visitPrimitiveClosure(tables, vertexId, visit);
  if (kind === "wire") for (const edgeId of tables.wires[id].edgeIds) visitPrimitiveClosure(tables, edgeId, visit);
  if (kind === "face") for (const wireId of tables.faces[id].wireIds) visitPrimitiveClosure(tables, wireId, visit);
  if (kind === "shell") for (const faceId of tables.shells[id].faceIds) visitPrimitiveClosure(tables, faceId, visit);
  if (kind === "solid") for (const shellId of tables.solids[id].shellIds) visitPrimitiveClosure(tables, shellId, visit);
};

const primitiveJsonFromId = (tables, metadataById, id, slot) => {
  const kind = resolvePrimitiveKind(tables, id);
  if (!kind) return null;
  const source =
    kind === "anchor" ? tables.anchors[id] :
    kind === "vertex" ? tables.vertices[id] :
    kind === "edge" ? tables.edges[id] :
    kind === "wire" ? tables.wires[id] :
    kind === "face" ? tables.faces[id] :
    kind === "shell" ? tables.shells[id] :
    tables.solids[id];
  return {
    kind,
    ...(slot ? { slot } : {}),
    ...source,
    ...(metadataById[id] ? { attributes: metadataById[id] } : {}),
  };
};

const collectObjectPrimitives = (tables, metadataById, object) => {
  if (Array.isArray(object.primitives)) return object.primitives;
  const slotById = new Map(Object.entries(object.primitives ?? {}).map(([slot, id]) => [id, slot]));
  const visited = new Set();
  for (const id of slotById.keys()) visitPrimitiveClosure(tables, id, (candidate) => visited.add(candidate));
  return [...visited]
    .sort((left, right) => {
      const leftKind = resolvePrimitiveKind(tables, left);
      const rightKind = resolvePrimitiveKind(tables, right);
      if (leftKind && rightKind && leftKind !== rightKind) return kindOrder[leftKind] - kindOrder[rightKind];
      return left.localeCompare(right);
    })
    .map((id) => primitiveJsonFromId(tables, metadataById, id, slotById.get(id)))
    .filter(Boolean);
};

const unownedRootIds = (tables, ownedIds) => {
  const childIds = new Set();
  for (const row of Object.values(tables.anchors)) childIds.add(row.attachment.id);
  for (const row of Object.values(tables.edges)) for (const id of row.vertexIds) childIds.add(id);
  for (const row of Object.values(tables.wires)) for (const id of row.edgeIds) childIds.add(id);
  for (const row of Object.values(tables.faces)) for (const id of row.wireIds) childIds.add(id);
  for (const row of Object.values(tables.shells)) for (const id of row.faceIds) childIds.add(id);
  for (const row of Object.values(tables.solids)) for (const id of row.shellIds) childIds.add(id);
  return [
    ...Object.keys(tables.solids),
    ...Object.keys(tables.shells),
    ...Object.keys(tables.faces),
    ...Object.keys(tables.wires),
    ...Object.keys(tables.edges),
    ...Object.keys(tables.vertices),
    ...Object.keys(tables.anchors),
  ].filter((id) => !ownedIds.has(id) && !childIds.has(id));
};

const normalizeModel = (rawModel) => {
  if (!rawModel || typeof rawModel !== "object") return rawModel;
  if (!Array.isArray(rawModel.objects)) return rawModel;
  if (!rawModel.geometry) return rawModel;

  const geometry = normalizeGeometry(rawModel);
  const tables = {
    anchors: Object.fromEntries(geometry.anchors.map((row) => [row.id, row])),
    vertices: Object.fromEntries(geometry.vertices.map((row) => [row.id, row])),
    edges: Object.fromEntries(geometry.edges.map((row) => [row.id, row])),
    wires: Object.fromEntries(geometry.wires.map((row) => [row.id, row])),
    faces: Object.fromEntries(geometry.faces.map((row) => [row.id, row])),
    shells: Object.fromEntries(geometry.shells.map((row) => [row.id, row])),
    solids: Object.fromEntries(geometry.solids.map((row) => [row.id, row])),
  };
  const metadataById = Object.fromEntries((Array.isArray(rawModel.metadata) ? rawModel.metadata : []).map((row) => [row.id, row.fields]));
  const objects = normalizeObjects(rawModel.objects);
  const ownedIds = new Set();
  const normalizedObjects = objects.map((object) => {
    const primitives = collectObjectPrimitives(tables, metadataById, object);
    for (const primitive of primitives) ownedIds.add(primitive.id);
    return {
      id: object.id,
      typology: object.typology,
      primitives,
      ...(object.attributes ? { attributes: object.attributes } : {}),
    };
  });

  for (const rootId of unownedRootIds(tables, ownedIds)) {
    const kind = resolvePrimitiveKind(tables, rootId);
    if (!kind) continue;
    const synthetic = {
      id: `object-${kind}-${rootId}`,
      typology: kernelTypology[kind],
      primitives: collectObjectPrimitives(tables, metadataById, { primitives: { [kind]: rootId } }),
    };
    for (const primitive of synthetic.primitives) ownedIds.add(primitive.id);
    normalizedObjects.push(synthetic);
  }

  normalizedObjects.sort((left, right) => left.id.localeCompare(right.id));
  return {
    schema: "spatial.model/v1",
    revision: typeof rawModel.revision === "number" ? rawModel.revision : 0,
    objects: normalizedObjects,
  };
};

for (const path of files) {
  const raw = JSON.parse(await readFile(path, "utf8"));
  const cleaned = raw && typeof raw === "object" && raw.schema === "spatial.modelspace/v1"
    ? {
        schema: raw.schema,
        revision: typeof raw.revision === "number" ? raw.revision : 0,
        models: Array.isArray(raw.models)
          ? raw.models.map((entry) => ({ id: entry.id, model: normalizeModel(entry.model) }))
          : [],
      }
    : raw;
  await writeFile(path, `${JSON.stringify(cleaned, null, 2)}\n`, "utf8");
}
'@; bun -e $script

